# Generated by `roundhouse --target futamura`. Do not edit: rerun the
# transpile instead.
#
# Query chains that Roundhouse found to be static, hoisted out of the
# request. Each `define` holds a chain's Relation with a bind placeholder
# for every value only known at request time. The first request on a
# connection kind builds it once, in Rails, so the SQL, the preload trees
# and the strict-loading setting are all Rails' own. Rails compiles it into
# an ActiveRecord::StatementCache, the mechanism behind `find_by`; each
# request only executes it, then does what Relation#load would have done
# next: mark association records the way AssociationRelation does, run the
# same Preloaders, and reverse a `last(n)`.
#
# The call site keeps the original chain as a block. It runs instead
# whenever a request-time value is one StatementCache refuses (nil, an
# Array, a Range, a record...), or when the built Relation turns out to need
# something a StatementCache cannot do (eager loading). With
# FUTAMURA_VERIFY=1 it runs as well, to check that both give the same
# records in the same order.
module Futamura
  Statement = Struct.new(:model, :build, :reverse, :one, keyword_init: true)
  Compiled = Struct.new(:cache, :preload, :strict_loading, keyword_init: true)

  @statements = {}
  @compiled = Concurrent::Map.new
  VERIFY = ENV["FUTAMURA_VERIFY"] == "1"

  class << self
    # `reverse:` for `last(n)`, whose rows Rails loads newest first and
    # reverses; `one:` for `first`/`last`/`take`/`find_by`, which return
    # the first loaded record or nil.
    def define(key, model, reverse: false, one: false, &build)
      @statements[key] = Statement.new(model: model, build: build, reverse: reverse, one: one)
    end

    def records(key, binds, owner: nil, association: nil, &fallback)
      return fallback.call if binds.any? { |value| ActiveRecord::StatementCache.unsupported_value?(value) }

      statement = @statements.fetch(key)
      model = statement.model
      compiled = nil
      records = model.with_connection do |connection|
        compiled = @compiled.compute_if_absent([key, connection.prepared_statements]) { compile(statement, connection) }
        compiled && compiled.cache.execute(binds, connection)
      end
      return fallback.call unless compiled

      if owner
        proxy = owner.association(association)
        records.each do |record|
          proxy.set_inverse_instance_from_queries(record)
          proxy.set_strict_loading(record)
        end
      end
      records.each(&:strict_loading!) if compiled.strict_loading

      scope = compiled.strict_loading ? ActiveRecord::Relation::StrictLoadingScope : nil
      compiled.preload.each do |associations|
        ActiveRecord::Associations::Preloader.new(records: records, associations: associations, scope: scope).call
      end
      records.reverse! if statement.reverse
      result = statement.one ? records.first : records

      verify(key, result, fallback.call) if VERIFY
      result
    end

    private

    # Build the Relation once and keep what loading it needs. `false` (not
    # nil, so compute_if_absent remembers it) when Rails would load it in a
    # way a StatementCache cannot reproduce.
    def compile(statement, connection)
      relation = nil
      cache = ActiveRecord::StatementCache.create(connection) { |params| relation = statement.build.call(params) }
      return false if relation.eager_loading? || relation.readonly_value || relation.extending_values.any?

      preload = relation.preload_values + relation.includes_values
      Compiled.new(cache: cache, preload: preload, strict_loading: relation.strict_loading_value)
    end

    def verify(key, result, expected)
      got = Array(result).map(&:id)
      want = Array(expected).map(&:id)
      raise "futamura #{key}: specialized #{got.inspect} != Rails #{want.inspect}" unless got == want
    end
  end
end
